import{_ as p,a0 as u,w as i,s as a,ao as l,I as n,x as e,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"當今世界的開源安全問題 | LCTT x X-CMD","titleTemplate":false,"description":"當今世界的開源安全問題 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"當今世界的開源安全問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"當今世界的開源安全問題 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221004 Security Issues With Open Source In Today-s World","title":"當今世界的開源安全問題","tag":"202210","desc":""},"relativePath":"202210/20221004 Security Issues With Open Source In Today-s World.md","filePath":"[post].md"}'),d={name:"202210/20221004 Security Issues With Open Source In Today-s World.md"};function m(f,t,T,x,w,y){const o=u("Link");return i(),a("div",null,[t[15]||(t[15]=l('<h1 id="當今世界的開源安全問題" tabindex="-1">當今世界的開源安全問題 <a class="header-anchor" href="#當今世界的開源安全問題" aria-label="Permalink to “當今世界的開源安全問題”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/10/160918vmfxmsm4bnwi0nb4.jpg" alt=""></p><blockquote><p>開源代碼可能是當今大多數公司最可行的選擇，但它也伴隨着自己的問題。</p></blockquote><p>許多人支持使用 <ruby>開源軟件<rt>open source software</rt></ruby>（OSS）。畢竟，我們為什麼要不斷地嘗試構建代碼來解決別人已經解決過的問題？為什麼不分享信息並逐步和迭代地增強當前的開源解決方案呢？這些<ruby>平等主義價值觀<rt>egalitarian values</rt></ruby>，可能是整個文明的根本，更不用説軟件了，但還是包含了幾千年來一直存在的衝突。</p><p>開源軟件安全的問題在於，儘管任何人都可以查看源代碼，但這並不意味着他們會這麼做。有一些廣泛使用的開源項目僅由數量有限的工程師維護。這些工程師無法完全自願地提供時間和精力，因為他們也需要支付他們的賬單。</p><p>即使對於更復雜的開源項目，這也是一個問題。舉個例子，Linux 內核項目由 3000 多萬行代碼組成，包含數百個需要解決的缺陷，並有近 2000 名活躍的開發者。每個活躍的開發者都寫了超過 15000 行的代碼。</p><p>根據 Linux 基金會最近的一項研究，一個應用程序平均有 5.1 個重大漏洞仍未解決，41% 的企業對其開源軟件的安全性缺乏信心。而更糟糕的是，只有 49% 的企業擁有開源安全策略。</p><p>即使開源軟件有安全漏洞，這也不能保證它能被修復。調查顯示，目前修復一個漏洞平均需要 97.8 天，使使用該軟件的企業在幾個月內容易受到攻擊。這就是開源軟件安全有時被忽視的地方：就像好人可以尋找代碼中的錯誤和漏洞來修復它們一樣，壞人也可以尋找同樣的漏洞來利用它們。</p><p>僅僅依靠志願者社區來發現漏洞、報告漏洞和修復漏洞是一個漫長的過程。在你繼續受益於開源的廣泛優勢的同時，花錢請人檢查你的開源解決方案的安全性可以幫助彌補這個問題。</p><p>由於必須部署開源軟件的更新和補丁以保證系統的安全，這一要求會帶來獨特的困難。如果你的解決方案依賴於某個軟件版本，更新你的關鍵任務軟件可能會導致功能損失和/或計劃外的停機。當情況對業務至關重要時，聘請專家來回傳補丁並維護一個時間更長的版本可能比讓大型社區願意去做更加優雅。</p><p>開源社區經常使用的一句話是：“這是開源的，去改變它吧！”它強調了一個關鍵點：當別人在項目中投入時間、精力或金錢的時候，期望白白得到良好的安全水平是不合理的，也是不可持續的。</p><p>要麼按原定計劃為開源做出貢獻，改進代碼併為他人發佈，要麼聘請專業人士管理開源代碼並在必要時進行調試，這些都是選擇。然而，這個行業無法承擔完全不做貢獻。</p><hr>',13)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),s(o,{href:"https://www.opensourceforu.com/2022/10/security-issues-with-open-source-in-todays-world/"},{default:r(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/10/security-issues-with-open-source-in-todays-world/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),s(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),s(o,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),s(o,{href:"https://github.com/KevinZonda"},{default:r(()=>[...t[4]||(t[4]=[e("KevinZonda",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const g=p(d,[["render",m]]);export{b as __pageData,g as default};
